{ id = "culla", strato = -1, x = 0.198, terreno = "legno", nome = T("La ninna nanna", "The lullaby"),
  ora = T("Di notte, la culla che dondola sotto la sua mano. Lui canticchia sottovoce sempre la stessa canzone. Fuori, la città dorme.",
          "At night, the cradle rocking under his hand. He hums the same song under his breath. Outside, the city sleeps."),
  allora = T("A te la cantava la nonna, la stessa. Non sapevi di ricordarne le parole finché non ti sono uscite dalla bocca.", "Grandma sang it to you, the same one. You didn't know you remembered the words until they came out of your mouth."),
  altro = { T("Il respiro piccolo si fa lungo, regolare. Si è addormentato.", "The little breath grows long, regular. He's asleep.") },
  macro = { "calore", "silenzio", "ricordo" }, macro_def = { 0.8, 0.4, 0.5 },
  musica = { tonica = 53, modo = "ionio", bpm = 52, metro = 3, prog = { 1, 4, 5, 1 }, accordo = "add9", battute = 2, glide = 14, tema = 0.35,
    canto = { str = "hum", ott = 0, amp = 0.335, contro = "musicbox" },
    drone = { amp = 0.335, cut = 1000, shape = 0.1, sub = 0.2, breath = 0.45 },
    linee = { l("arpeggio", "musicbox", 1, 0.14, 0.5), l("accordo", "strings", 0, 0.14, 0.5, { atk = 3 }), l("basso", "pluck", -1, 0.168, 0.5) },
    tex = { breath = 0.14, clock = 0.084, city = 0.07 }, fx = { rev = 0.7, size = 0.88, tape = 0.12 } } },

{ id = "lavatrice", strato = -1, x = 0.336, terreno = "piastrelle", nome = T("La lavatrice", "The washing machine"),
  ora = T("Seduto per terra davanti all'oblò, a guardare i panni che girano. Il ronzio, la centrifuga che scuote il pavimento.",
          "Sitting on the floor in front of the porthole, watching the clothes go round. The hum, the spin cycle shaking the floor."),
  allora = T("Era la tua televisione, da piccolo. Il calzino rosso tra le lenzuola bianche era il cattivo del film.", "It was your television as a child. The red sock among the white sheets was the villain of the film."),
  altro = { T("La centrifuga parte, e tutta la casa sembra voler decollare.", "The spin starts, and the whole house seems ready to take off.") },
  macro = { "ritmo", "macchine", "infanzia" }, macro_def = { 0.6, 0.4, 0.5 },
  musica = { tonica = 48, modo = "misolidio", bpm = 80, prog = { 1, 7, 4, 1 }, accordo = "settima", battute = 2, glide = 8, tema = 0.25,
