{ id = "cena_silenzio", strato = -1, x = 0.472, terreno = "legno", nome = T("La cena in silenzio", "Dinner in silence"),
  ora = T("Tutti a tavola, e nessuno parla. Solo le forchette sui piatti, il bicchiere posato, l'orologio. Qualcosa è successo.",
          "Everyone at the table, and nobody speaks. Only forks on plates, a glass set down, the clock. Something has happened."),
  allora = T("Non hai mai saputo cosa. Ricordi solo che hai mangiato tutto, anche la verdura, per non dare fastidio.", "You never found out what. You only remember eating everything, even the vegetables, so as not to be a bother."),
  altro = { T("Qualcuno si schiarisce la voce. Poi niente.", "Someone clears their throat. Then nothing.") },
  macro = { "silenzio", "ritmo", "tormento" }, macro_def = { 0.5, 0.4, 0.15 },
  musica = { tonica = 47, modo = "eolio", bpm = 58, prog = { 1, 6, 4, 5 }, accordo = "add9", battute = 4, glide = 14, tema = 0.25,
