{ id = "porta_chiusa", strato = -1, x = 0.608, terreno = "legno", nome = T("La porta chiusa", "The closed door"),
  ora = T("Dietro la porta, voci che si alzano. Lui è seduto per terra nel corridoio, le ginocchia strette. Le parole non si capiscono, il tono sì.",
          "Behind the door, voices rising. He sits on the corridor floor, knees pulled in. You can't make out the words, but you can the tone."),
  allora = T("Ti mettevi le mani sulle orecchie e contavi. Se arrivavi a cento prima che smettessero, tutto sarebbe andato bene.", "You put your hands over your ears and counted. If you reached a hundred before they stopped, everything would be all right."),
  altro = { T("La porta si apre. Una mano sui capelli: va a dormire, non è niente.", "The door opens. A hand on your hair: go to sleep, it's nothing.") },
  macro = { "voci", "tormento", "battito" }, macro_def = { 0.5, 0.25, 0.4 },
  musica = { tonica = 46, modo = "frigio", bpm = 64, prog = { 1, 2, 1, 7 }, accordo = "grappolo", battute = 2, glide = 12, tema = 0.15, urgenza = 0.4, ostinato = "pluck",
