    tex = { voices = 0.4, heart = 0.2 }, fx = { rev = 0.4, size = 0.65, dark = 0.3 }, speciale = { hrate = 1.7 } } },

{ id = "valigia", strato = -1, x = 0.743, terreno = "legno", nome = T("La valigia", "The suitcase"),
  ora = T("La valigia aperta sul letto. Dentro ci va una vita intera, piegata male. Il treno è domani alle sei.",
          "The suitcase open on the bed. A whole life goes in, badly folded. The train is tomorrow at six."),
  allora = T("La prima volta che sei andato via da casa. Tua madre ti aveva messo un barattolo di sugo tra i maglioni, avvolto nel giornale.", "The first time you left home. Your mother had put a jar of sauce among your jumpers, wrapped in newspaper."),
  altro = { T("Non si chiude. Ci si siede sopra. Si chiude.", "It won't close. He sits on it. It closes.") },
