    tex = { clock = 0.1, rain = 0.1 }, fx = { rev = 0.6, size = 0.85, tape = 0.15, age = 0.15 } } },

{ id = "giradischi", strato = -1, x = 0.878, terreno = "moquette", nome = T("Il giradischi", "The record player"),
  ora = T("La puntina scende, il fruscio, poi la musica. Lui balla da solo in salotto, con gli occhi chiusi, piano.",
          "The needle drops, the crackle, then the music. He dances alone in the living room, eyes closed, slowly."),
  allora = T("I dischi di tuo padre, con le copertine consumate. Te li faceva ascoltare sdraiato sul tappeto, e ti spiegava dove entrava il contrabbasso.", "Your father's records, with worn sleeves. He made you listen lying on the rug, and told you where the double bass came in."),
  altro = { T("Il disco finisce. Il braccio torna indietro da solo. Il fruscio continua.", "The record ends. The arm returns by itself. The crackle goes on.") },
  macro = { "ritmo", "fragilita", "calore" }, macro_def = { 0.6, 0.4, 0.7 },
  musica = { tonica = 50, modo = "dorico", bpm = 76, prog = { 2, 5, 1, 6 }, accordo = "settima", battute = 2, glide = 8, tema = 0.35,
